#define OS_DEF_GLOBAL_VAR(type, name, addr)                                    \
    /* Memory-mapped value for direct access */                                \
    type OS_##name DECL_ADDRESS(addr);                                         \
    __DEF_ADDR_OFFSETS(name, addr)

