#define BT_EVT_TO_NCI_LP            0x4400      /* Low power */
#define BT_EVT_TO_NFC_ERR           0x4500      /* Error notification to NFC Task */

#define BT_EVT_TO_NFCCSIM_NCI       0x4a00      /* events to NFCC simulation (NCI packets) */

/* HCISU Events */

