    u8 mButtonHoldTimersTurbo[MAX_PAD_INPUT_FLAGS]; //0x18
    u8 mButtonHoldTimers[MAX_PAD_INPUT_FLAGS]; //0x38

    //Stick/trigger inputs
    u8 mLStickX; //0x58
    u8 mLStickY; //0x59
